UPDATE trip_plan
SET title = #{title}
WHERE trip_plan_id = #{tripPlanId}

UPDATE trip_item
SET seq_order = seq_order + 1000
WHERE trip_plan_id = #{tripPlanId}

UPDATE trip_item
SET event_content_id = NULL, place_content_id = NULL
WHERE trip_plan_id = #{tripPlanId}
  AND trip_item_id IN

	#{itemId}

UPDATE trip_item
SET seq_order = #{seqOrder}
WHERE trip_item_id = #{tripItemId}
  AND trip_plan_id = #{tripPlanId}

mapper.delete:
DELETE FROM trip_item
WHERE trip_item_id = #{tripItemId}
  AND trip_plan_id = #{tripPlanId}

mapper.select:
SELECT event_content_id, event_name, event_type, district_name, event_place, date_text, free_yn,
       display_yn, event_start_date, event_end_date, event_start_time, event_end_time, mapx, mapy
FROM event
WHERE display_yn = TRUE
  AND mapx IS NOT NULL AND mapy IS NOT NULL
  AND event_start_date <= #{visitDate}
  AND event_end_date >= #{visitDate}

  AND event_type IN
      #{type}


  AND district_name = #{district}


  AND free_yn = TRUE

ORDER BY event_end_date, event_content_id
LIMIT #{limit}
